from pathlib import Path
import json,hashlib,sys
G=Path('C:/Github/DecenniumDescent');R=G/'DescentReviewChanges/ReviewBible';A=G/'docs/audit/2026-10-08/full-game';D=R/'data/playtest/spell_drafts'
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
compact=lambda x:json.dumps(x,ensure_ascii=False,separators=(',',':'),sort_keys=True)
def dump(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
source=read(D/'candidate_evocation_cantrips_sources.json');src={s['id']:s for s in source['spells']}
cat=read(R/'data/public/spell_playtests/catalog.json')['spells'];by={s['id']:s for s in cat}
prior={s['id']:s['operational'] for s in cat if s['operational']}
assert len(prior)==237 and all(not by[i]['operational'] for i in src)
review='docs/audit/2026-10-08/full-game/GPT_EVOCATION_CANTRIP_SOURCE_CONFERENCE.md'
clarification='docs/audit/2026-10-08/full-game/GPT_EVOCATION_CANTRIP_AUTHORING_CLARIFICATION.md'
assert 'SOURCE-RECONCILED / DRAFTABLE' in (G/review).read_text(encoding='utf-8')
assert 'broad current-HP-gain prohibition' in (G/clarification).read_text(encoding='utf-8')
common=' Actual class/source access, repertoire, action availability, components, RP, Dissonance/Refrain, concentration transitions, paid commitment and cast/counter/outcome hooks follow SPELL_INTEGRATION_RULES.md. Base rank 0 costs 0 RP but does not waive real extra costs or Refrain. V requires audible speech; S requires the ordinary usable free hand or an actual exception. No F is added. Spell attacks use d20 + PB + actual casting modifier against AC; natural 1 misses, natural 20 hits and doubles only actual damage dice. Saves use DC 8 + PB + actual casting modifier and binary-save rules. An illegal uncommitted attempt supplies no effect; a legally paid cast countered or failing afterward refunds nothing. Actual damage/material/condition defenses retain their own scopes. No automatic level scaling, extra action budget or resource generation.'
ending='The rider ends at the target’s first future regular-turn END, excluding its entire current turn if already underway. Outside initiative it ends six elapsed seconds after application. Preserve the original regular/virtual marker or outside absolute deadline through initiative changes, extra turns, absence and travel; end-phase events precede expiry cleanup.'
minute='In initiative the maximum ends at the caster’s tenth future regular-turn START after application, excluding any start already underway/passed. If begun outside initiative the maximum is 60 elapsed seconds. Preserve that original regular/virtual marker or absolute deadline across initiative changes, extra turns, absence and travel; no timing-mode change resets it.'
rider=' A hit establishes the independent rider under its own defenses even if the damage is reduced to 0; immunity to the damage type alone does not prevent that rider. A later independent application retains its own endpoint; ending one removes only that application, and equal penalties/prohibitions do not stack magnitude.'
rows=[]
def add(i,activation,range_ft,targets,duration,conc,resolution,effect,limits,notes):
 s=src[i];rows.append({'id':i,'activation':activation,'rangeFeet':range_ft,'targets':targets,'duration':duration,'concentration':conc,'components':['V','S'],'resolution':resolution,'effect':effect,'scaling':'None. No automatic increase in damage, range, target count, duration, uses or magnitude.','limitations':limits+common,'designNotes':notes,'implementationStatus':'LOCAL CANDIDATE — source-reconciled; exact manuscript review pending; not selectable','sourcePlacements':s['sourcePlacements'],'sourceCoreEntries':s['sourceCoreEntries'],'classAccessEvidence':s['classAccess'],'sourceReview':[review,clarification],'reviewEvidence':[]})

add('freezing-touch','Action',5,
'One creature you perceive and can physically touch within your actual legal reach, with line of effect. The 5-foot reference describes ordinary Touch reach; the spell does not grant extended reach.',
'Instantaneous damage; delayed Speed rider during one next-regular-turn window, no concentration. Follow the explicit onset/expiry procedure in Effect, rather than applying an immediate one-round slow.',False,
'Make one melee spell attack. Miss: no damage or scheduled rider. Hit: deal 1d4 cold and establish one pending -5-foot Speed rider under its own defenses.',
'In initiative, schedule onset at the target’s next future regular-turn START, excluding any current turn entirely, and expiry at that same future regular turn’s END. There is no immediate slowing. Start processing precedes voluntary movement; end-phase events precede expiry. If initially cast outside initiative, schedule onset at application +6 elapsed seconds and expiry at +12. If initiative begins while onset is pending, map onset to the next actual regular target START even if before original +6; expiry is the earlier of that affected regular END and original +12. No +6 not-before floor remains, and reaching +12 first ends the pending rider without later activation. If initiative begins after outside onset has occurred, the active rider simply retains its original +12 expiry, with no new full-turn window. Effects initially created in initiative preserve both original future START and corresponding END as virtual markers on exit; no restart. Extra turns neither activate nor consume these regular markers, but an already-active rider affects movement during an extra turn within its active interval. Compute Speed with the existing strongest adverse slow from pre-control Speed, minimum 0, followed by independently applicable system modifiers; retain already-spent movement.',
'Multiple Freezing Touch penalties never add -5 repeatedly. Each hit can schedule a separate future window; a hit during an already-slowed regular turn may schedule its next regular turn. Pending/active records retain their own endpoints through suppression, absence, initiative reordering and travel. No Frozen, Rooted, forced movement or whole-Action denial is added.'+rider,
'PRESERVED: Action, Touch, V/S, 1d4 cold and -5 feet next turn. NEW: melee spell attack; hit-based independent Speed rider; delayed next-regular-START/END window; outside +6/+12 and exact initiative-entry transition with retained +12 cap. This is not an immediate generic one-round slow.')

add('flame-lash','Action',30,
'One creature or independently legal object target you perceive within 30 feet and line of effect. An object worn/carried by an unwilling creature needs an actual separate object-targeting permission; this spell grants none.',
'Instantaneous spell; any ignited ordinary fuel continues only as a mundane fire under its own material/environmental rules. No concentration.',False,
'Make one melee spell attack with 30-foot reach, against the actual target AC. Miss: no damage or ignition. Hit: deal 1d6 fire; check the independently scoped object-ignition rider.',
'If the actual hit target is an ordinary flammable object/portion with adequate fuel that can sustain mundane ignition, ignite it subject to actual material, ignition and fire defenses. This is an independent successful-hit rider rather than a positive-damage trigger. The resulting flame uses ordinary mundane-fire procedures. Nonflammable or saturated material does not become combustible. Creature damage does not automatically ignite clothing, armor, hair or carried equipment.',
'This unusual 30-foot reach belongs solely to this melee spell attack. It changes no general melee reach, threatened area, opportunity-attack reach, weapon reach or other spell. It grants no additional opportunity attack. No automatic Burning condition, conjured fuel, environmental damage packet or secondary object attack. Legal object defenses and durability remain; ignore none merely because a target is flammable.',
'PRESERVED CONFLICT: the effect says melee range while metadata says 30 feet. The reviewed NEW reconciliation is a 30-foot melee spell attack, retaining both original statements. NEW: attack resolution, actual legal object defenses and hit-based ignition boundary. It is not a rewrite to ranged damage or ordinary Touch reach.')

add('soundburst','Action',5,
'Choose a perceived point within 5 feet and line of effect. Affect every creature in a 5-foot-radius sphere centered there with line of effect from the center, including yourself and allies when geometrically included; no selective omission.',
'Instantaneous damage; one target-round Deafened, no concentration. '+ending,False,
'Each affected creature independently makes a Constitution save. Success: no damage or Deafened. Failure: take the shared 1d4 thunder result and independently attempt actual Deafened under its own defenses.',
'Roll 1d4 thunder once for the cast and use that same raw result for all failed saves, applying each target’s own damage defenses separately. Failed saves apply actual Deafened: use its existing hearing consequences. Thunder resistance/immunity affects damage only unless it also expressly protects hearing/the rider; Deafened immunity prevents only that component. Neither failed-save component requires positive damage from the other.',
'The sphere is an initial snapshot, not a persistent zone or entry aura. No Stunned, forced movement, concentration loss, extra save, automatic Burning or generic hard-control claim. Each Deafened application has its own endpoint; removing one leaves unrelated sources. Ordinary noise follows actual hearing/environmental rules, with no invented fixed alarm radius.',
'PRESERVED: Action, range5, 5-foot AoE, V/S, CON save negates, 1d4 thunder and Deafened one round. NEW: perceived center, 5-foot-radius sphere/all creatures, shared damage roll, independent defenses and explicit future-target-END clock.')

add('minor-combustion','Action',30,
'One ordinary flammable object or flammable portion you perceive within 30 feet and line of effect: unattended, held by you, or held/carried/worn by a willing creature. No direct creature target or unwilling creature’s carried/worn utility auto-target.',
'Instantaneous ignition, no concentration. The resulting ordinary flame lasts only as its actual fuel/environment permit.',False,
'Automatic ignition of an eligible torch, candle, lamp wick, tinder bundle or comparable ordinary combustible object/portion no larger than roughly 1 cubic foot and 10 pounds. Actual hidden fuel/ignitability defenses resolve after paid commitment without a free diagnostic; an ineligible target gains no effect or substitute.',
'Light the eligible material with the ordinary flame that its existing fuel can sustain. Dry wood, wick/oil and tinder can work. The spell does not render stone, metal, saturated material or other nonignitable matter combustible. A small ignited object/portion can subsequently spread flame or cause hazards under actual mundane environmental rules.',
'No fuel, oil, torch, resource, spell damage packet or Burning condition is created. The size boundary applies to the initially ignited portion, not immunity to ordinary subsequent spread. The spell does not erase expedition Supply or grant a special arson damage formula. It is not a creature attack or a way to bypass unwilling custody by naming a small carried portion.',
'PRESERVED: Action, 30 feet, V/S, instantaneous torch/small-object lighting. NEW: roughly 1-cubic-foot/10-pound initial portion cap, physical fuel eligibility and unattended/self-held/willing-carried target procedure. Ordinary later fire hazards remain possible.')

add('force-needle','Action',30,
'One creature or independently legal object you perceive within 30 feet and line of effect. This spell grants no separate permission to target an unwilling creature’s worn/carried item.',
'Instantaneous, no concentration.',False,
'Make one ranged spell attack against actual AC. Ignore AC bonuses from partial/intervening cover that does not fully block line of effect. Hit: deal 1d6 piercing. Miss: no damage.',
'The needle deals piercing damage, despite its name. Its cover exception removes only the applicable non-total-cover AC bonus from this attack. Other real attack modifiers, defenses, object durability and piercing resistance/immunity still apply.',
'Total cover still blocks direct targeting and line of effect. The spell provides no wall penetration, location oracle, armor bypass, resistance bypass or force damage. No secondary target, ricochet or lingering object is created.',
'PRESERVED: Action, 30 feet, V/S, 1d6 piercing and ignores cover. NEW: ranged spell attack and explicit limitation of cover bypass to non-total-cover AC. Both broad original wording and this reviewed provisional boundary remain recorded.')

add('arcane-echo','Bonus Action',30,
'One willing creature, including yourself, that you perceive within 30 feet and line of effect. No ongoing range/line-of-effect tether is created after legal application.',
'Pending arm: up to one minute, no concentration. '+minute+' A generated repeat has its separate recipient-clock expiry described in Effect; consuming/expiring the old arm never expires that independent repeat.',False,
'On successful resolution establish one pending Arcane Echo arm on the recipient; a new successful arm replaces only their older arm, across all casters. A countered/failed new application replaces nothing. At the recipient’s next legally committed qualifying cast, consume the arm and generate one repeat permission before its counter window. An illegal uncommitted attempt does not consume it.',
'A qualifying original has actual rank 0 through its chosen class/source, a selected mode with a printed damage payload, and actual committed Action activation. Whether it later hits, is saved against, deals 0 or is countered does not alter qualification. Ready preparation of an Action damaging cantrip qualifies at actual cast commitment; its later release is not another cast. An actual feature conversion to Bonus Action/Reaction does not qualify. Record the original spell ID, actual class/source, school, rank-0 placement and selected damaging mode. Generate one permission to cast that SAME provenance again as a Bonus Action; a new generated permission replaces any older unused repeat on that recipient. It is usable after the original’s entire cast/interrupt stack has resolved, including later that same turn if a legal Bonus Action remains. It expires at the recipient’s first future regular-turn END, excluding the entire recipient current turn if already underway; outside initiative, six elapsed seconds after qualifying commitment. Preserve its original regular/virtual endpoint or absolute deadline across timing changes. At repeat commitment revalidate actual current repertoire/access, components, legal targets and parameters within that same mode, costs and Bonus Action availability. New legal targets/points/parameters are allowed, but no class/school/rank/mode substitution. Consume the repeat permission at its own legal paid commitment, even if later countered/missed/saved against/0damage. The repeat is a genuine independent spell cast with its own rolls, counter window, actual costs, concentration transitions, Dissonance/Refrain and normal cast/outcome hooks. Only its casting type becomes Bonus Action; none of that action budget is granted.',
'An Echo-generated repeat can NEVER trigger another Arcane Echo arm, even if a feature changes it back to Action. Other independently qualified normal casts can trigger a later arm. Arcane Echo itself has no damaging mode and cannot qualify. One pending arm and one already-generated repeat may coexist per recipient; a new arm alone does not erase the existing repeat, and the consumed arm’s later expiry cannot erase it. No indefinite stocking, copied spell knowledge, free components, resource duplicate or same-ID cross-class/rank access. A repeat cannot commit inside the original’s pending interrupt stack. A Readied original may remain held after preparation while a later repeat is cast; actual concentration/holding transitions still apply. Countering or ending either independent cast does not revive/refund/cancel the other. Refrain uses actual chronological casts, including any intervening cast; the original and repeat are not assumed consecutive merely because they share identity.',
'PRESERVED: Bonus Action, 30 feet, V/S and next damaging cantrip cast again as Bonus Action. NEW: willing recipient, nonconcentration one-minute arm replacing Instantaneous metadata, actual Action/rank0 damaging-mode qualifier, Ready commitment binding, locked provenance, independent next-recipient-END repeat, normal fresh-cast hooks/costs and lineage recursion guard. This is an actual cast, expressly distinct from generic copy exclusions; Universal Cantrip Echo remains a separate source identity.')

add('shocking-grasp','Reaction',30,
'Only the triggering creature: one you perceive within 30 feet and line of effect when it begins an Action on its own actual turn, including an extra turn. This source has no Touch requirement.',
'Instantaneous damage; one target-round restriction on future Reaction commitments, no concentration. '+ending,False,
'Trigger after the target’s Action commits and its begin hooks occur, before its first main outcome. A Bonus Action, Reaction or movement segment is not this trigger. Spend a legal available Reaction and commit this cast, then resolve its counter/interrupt stack. Make one ranged spell attack against the still-legal triggering target. Miss: no damage or denial. Hit: deal 1d8 lightning and bar new Reaction commitments for the rider’s duration.',
'The triggering Action is not canceled and its paid costs remain; resume it after surviving interrupts if it still exists. Once Shocking Grasp legally commits, its triggering Action is not an ongoing tether: if another nested legal interrupt cancels that Action, Shocking Grasp still resolves against its still-legal target without reviving/refunding the parent. The no-Reactions rider applies only to future commitments; no already-committed Reaction on the current stack is erased. A normal later Reaction refresh cannot overcome the still-active prohibition, but expiry itself grants no refresh.',
'An actual legal action sequence must supply the trigger outside initiative; do not manufacture repeatable free pre-initiative Reaction casts or budgets. It grants no metal-armor advantage, Action cancellation, extra attack or hard whole-Action control. The spell’s broad Reaction trigger remains an explicit human-balance question. Current-turn exclusion applies to duration even though that current Action supplied the trigger.'+rider,
'PRESERVED: printed Reaction, 30 feet, V/S, 1d8 lightning and no reactions. NEW: perceived own-turn Action-start trigger after commitment/before outcome; ranged spell attack; hit-based prospective denial until future target END; parent-independent paid interrupt. Do not import an Action/Touch version from another ruleset.')

add('dancing-lights','Action',30,
'Choose one to four distinct perceived points within 30 feet and line of effect, outside solid matter. Actual Evocation or Illusion class/source access determines generating school; both use these same mechanics.',
'Concentration, up to one minute. '+minute,True,
'On successful resolution create up to four nonphysical torch-sized lights at the chosen points. One active Dancing Lights application per caster across school placements. A successful new application replaces that caster’s prior set; normal concentration transition may already have ended it at new cast commitment, and a countered cast restores nothing.',
'Each light provides real ordinary illumination: bright light in a 10-foot radius and dim light for an additional 10 feet. This is usable illumination even from an actual Illusion placement. As one existing Bonus Action, consciously move any/all surviving lights once, each along a continuous non-solid path no longer than 30 feet. Each new destination must be perceived with line of effect from the caster and within 60 feet. The path may curve around obstacles but never pass through solid matter, teleport or exceed its actual distance budget. The 60-foot caster-to-light tether is checked continuously during movement of caster or light: exceeding it ends that light immediately, even if a proposed path would later return. One light ending leaves the rest. Losing caster-to-light line of effect after creation does not itself end an unmoving light; it still illuminates subject to ordinary physical barriers. A later command still needs its destination’s perception/line of effect. Lights otherwise stay at their points; no automatic following, formation lock or autonomous movement.',
'Opaque barriers block ordinary illumination. Overlapping sets/radii do not add together into greater range or a higher light category merely by stacking. No heat, fuel, sunlight trait, damage, physical object, collision, attachment, automatic Invisible/Hidden revelation or generic magical-darkness dispel. Ordinary lighting can remove mundane darkness as the actual reason something was unseen; other concealment/senses remain. Commands grant no extra Bonus Action. Loss of concentration, actual removal or expiry ends the relevant lights; a stale endpoint of an older replaced set cannot erase its replacement. Actual multiple-concentration features do not bypass the one-set-per-caster cap.',
'PRESERVED: both Evocation/Illusion placements and class access, Action, 30-foot creation range, V/S, up to four torch-sized lights. NEW: concentration minute replacing Instantaneous placeholder, real 10-foot bright/additional10dim radii, Bonus Action movement up to30, continuous60foot tether and no ongoing-LoE destruction. No canonical torch radius is claimed; broader lighting runtime and numerical balance remain open.')

add('acid-splash','Action',30,
'Choose one or two distinct targets you perceive within 30 feet and line of effect: creatures, unattended objects, or one of each. No distance-between-targets requirement is imposed. No separate worn/carried object target.',
'Instantaneous, no concentration.',False,
'Each chosen creature independently makes a Dexterity save. Success: no damage. Failure: take 1d6 acid. A legally chosen unattended object automatically receives the failed-save damage result, with its actual material/damage defenses and durability; it receives no invented creature save. Roll the 1d6 once and share its raw result among both targets as applicable.',
'Apply each target’s actual acid defenses separately to the shared damage result. The spell affects only the one or two chosen entities, with no damage to neighbors, carried equipment or a surrounding area.',
'No residual pool, ongoing acid, corrosion, armor penalty or condition. A future explicit worn/carried-object override must supply both eligibility and resolution; this card supplies neither. No owner save or automatic unattended classification is invented. The two targets can be anywhere within their individual legal range/line of effect, without an imported 5-foot separation cap.',
'PRESERVED: Action, 30 feet, V/S, 1d6 acid to one or two targets. NEW: creature DEX saves, shared damage roll and explicit unattended-object automatic damage procedure; the authoring clarification excludes separate worn/carried items. No source-required proximity restriction exists.')

add('chill-touch','Action',5,
'One creature you perceive and can physically touch within your actual legal reach, with line of effect. The 5-foot reference describes ordinary Touch reach; no extended reach is granted. Use the actual Evocation or Necromancy placement available to the chosen class; access is not unioned.',
'Instantaneous damage; one target-round broad current-HP-gain prohibition, no concentration. '+ending,False,
'Make one melee spell attack. Miss: no damage or restriction. Hit: deal 1d8 necrotic and establish the independent HP-gain prohibition under its actual defenses.',
'While affected, any event increasing the target’s current HP produces 0 gain: spell/feature/potion healing, passive regeneration, natural recovery, natural-20 death-save 1HP, Stable-state 1HP and other direct restoration. Apply HEALING_DEATH_PLAYTEST.md: ordinary healing’s legal amount and genuine excess become0; ordinary activation costs remain committed, while a reserve spent only for actual restored HP spends0. Independent non-HP components still resolve. A blocked natural20 uses the already-reviewed bridge: Stable at0, death counters cleared, immediate d4-hour recovery deadline and preserved used-turn marker. A due Stable1HP recovery remains subject to its existing blocked-deadline procedure; this spell never rerolls or resets that deadline.',
'No Undead/biological target prerequisite or special Undead rider. The prohibition does not itself block stabilization, successful death-save state changes, temporary HP, condition removal, damage prevention, maximum-HP changes or independent non-HP components. A maximum-HP change does not authorize a separate current-HP increase through this prohibition. Actual resurrection returned HP is the existing LIFE TRANSITION exception and is not blocked; no corpse/soul/resurrection seal is created. Actual death/condition-removal procedures retain their scope, without duplicating an identity or refreshing spent resources. This is an HP-state rule, not a cosmology ruling.'+rider,
'PRESERVED: both Evocation/Necromancy sources and actual access, Action, Touch, V/S, 1d8 necrotic and cannot regain HP. NEW: melee spell attack, hit-based independent broad current-HP-gain prohibition, explicit future-target-END duration, state-recovery bindings and existing resurrection life-transition boundary. Authoring clarification deliberately refines initial conference healing-only wording to the source’s broader HP-gain scope.')

add('thunderclap','Action',5,
'Every creature within a 5-foot-radius sphere centered on you with line of effect from you, including yourself and allies. No selective omission or separate perception prerequisite for individual area occupants.',
'Instantaneous, no concentration.',False,
'Each affected creature independently makes a Constitution save. Failure: take 1d6 thunder. Success: no damage. Roll damage once and use the shared raw result for all failed saves, applying each target’s own defenses.',
'Resolve one initial caster-centered thunder burst against its snapshot of creatures. The printed all-creatures scope includes its caster. The sound is ordinarily perceptible under actual hearing and environmental rules; no fixed hundred-foot alarm radius is supplied.',
'No Deafened, Stunned, forced movement, object damage or continuing aura. This rank-0 identity thunderclap is separate from rank-1 Thunder Clap (thunder-clap); knowing one grants no access to the other. The caster’s inclusion remains an explicit human-balance question, not a silently removed source consequence.',
'PRESERVED: Action, range5, V/S, 1d6 thunder to ALL creatures within5 feet. NEW: caster-centered sphere/line of effect, CON save negates and shared damage roll. No caster exemption or unrelated-game auditory distance is imported.')

add('poison-spray','Action',10,
'One creature you perceive within 10 feet and line of effect. No breathing, inhalation, biological-body or creature-type eligibility requirement.',
'Instantaneous, no concentration.',False,
'The target makes the printed Constitution save. Failure: take 1d12 poison. Success: no damage. There is no attack roll.',
'Deal the source’s 1d12 poison packet on a failed save, subject to actual poison resistance/immunity and other applicable defenses. Creature type alone adds no extra exclusion beyond its actual defenses.',
'No Poisoned condition, persistent cloud, ongoing damage, second target or incidental equipment/environmental damage. Damage remains1d12 at every level under this source; no generic scaling is inferred.',
'PRESERVED: Action, 10 feet, V/S, 1d12 poison and CON save negates. NEW completion is explicit one-perceived-creature/line-of-effect targeting; no unrelated physiological restriction is invented.')

